window.APPLICATION_PROFILES=[{"id":"kdl","role":"AI 솔루션 운영 엔지니어","headline":"AI 기능을 호출 가능한 서비스로 만들고, 운영 문제를 추적해 개선합니다.","summary":"문서·음성 AI 파이프라인을 인수해 처리 지연과 한글 인식 문제를 개선하고, Node.js API·Nginx·HTTPS 배포를 단독 담당했습니다. HTM에서는 AWS 운영 환경 분리와 staging 자동화를 설계·적용했습니다. AI 솔루션을 실제 환경에서 사용할 수 있도록 연결하고 운영 이슈를 해결한 경험을 보유하고 있습니다.","order":["document-ai","htm","vision","mangwon"]},{"id":"waion","role":"백엔드 / Product Engineer","headline":"사용자의 업무를 규칙과 데이터 흐름으로 정리하고 서비스로 연결합니다.","summary":"HTM에서 매장 근태·스케줄·채용 업무의 요구사항과 시스템·화면 흐름을 설계하고 AI를 활용해 구현·배포·운영을 진행했습니다. 계정과 조직 소속, 채용 확정 후 직원·매장 배정 흐름을 구성했으며 AWS 운영 환경과 배포 구조도 개선했습니다. Node.js 기반 AI API와 외부 LLM API 연동 경험을 보유하고 있습니다.","order":["htm","document-ai","mangwon","vision"]},{"id":"medistream","role":"EMR/CRM Product Engineer","headline":"현장의 업무 흐름을 이해하고, 피드백을 기능과 운영 개선으로 연결합니다.","summary":"HTM의 근태·스케줄·채용 흐름을 요구사항과 업무 규칙으로 정리하고, 시스템 구조·화면 흐름 설계부터 AI 활용 구현·운영 대응까지 진행했습니다. 계정·조직 소속과 채용 후 배정 흐름을 구성하고, 실제 운영에 영향을 준 AWS 환경 공유 문제를 분리 구조로 변경했습니다. 현업 업무를 사용 가능한 시스템으로 구체화한 경험이 있습니다.","order":["htm","mangwon","document-ai","vision"]},{"id":"mayi","role":"Backend Engineer","headline":"영상 분석 결과를 API·통계·보고서로 연결하고, 처리 병목을 개선합니다.","summary":"CCTV 분석 파이프라인의 병목을 모듈 단위로 추적해 오토라벨링 작업을 당시 테스트에서 1시간 이내에 완료하도록 개선했습니다. RTSP 군중 분석 결과를 Kafka·Redis와 연계하고, 00시장 방문객 통계를 뷰어·ChatGPT API 보고서로 연결했습니다. AI 처리 결과의 서비스 연동과 AWS 운영 구조 개선 경험이 있습니다.","order":["vision","mangwon","document-ai","htm"]},{"id":"jnpmedi","role":"AI Driven Product Engineer","headline":"업무의 의사결정 흐름을 설계하고, AI와 협업해 실제 제품으로 연결합니다.","summary":"HTM에서 요구사항·업무 규칙과 시스템·화면 흐름을 설계하고, Claude Code를 활용해 구현·배포·운영을 진행했습니다. 공유 인프라의 운영 간섭에 대응해 EC2·RDS 환경 분리와 필요 시 staging 운영을 설계·적용했습니다. 문서·음성 AI 처리 코드의 인수·정제·API 배포 경험을 바탕으로 업무와 AI 시스템의 연결을 구체화합니다.","order":["htm","document-ai","vision","mangwon"]},{"id":"connectwave","role":"메이크샵 프라이빗 클라우드 엔지니어","headline":"서비스 운영에서 드러난 자원·환경 문제를 분리와 자동화로 개선합니다.","summary":"HTM의 공유 EC2·RDS 환경에서 staging 배포·예약 작업·자원 부족·DB 병목이 운영에 영향을 주자 staging과 production 인스턴스를 분리했습니다. 필요 시 staging을 기동·중지하고 DB를 동기화하는 GitHub Actions 운영 방식을 설계·적용했습니다. AI API 서버와 Nginx·HTTPS 배포, 운영 환경 변경 경험도 보유하고 있습니다.","order":["htm","document-ai","vision","mangwon"]},{"id":"miridih","role":"미리캔버스 Product Engineer","headline":"AI 처리 결과를 사용자가 다루는 화면·데이터·업무 도구로 만듭니다.","summary":"00시장 방문객 통계를 생성하고 WinForms 조회·비교 도구와 HTML·ChatGPT API 보고서를 구성했습니다. 문서·음성 AI 파이프라인의 데이터 정제·형식 변환을 개선했으며, HTM에서는 업무 규칙·화면 흐름 설계와 AI 활용 구현·운영을 진행했습니다. 데이터와 AI 기능을 실제 업무에서 사용하는 도구로 연결한 경험이 있습니다.","order":["mangwon","document-ai","htm","vision"]},{"id":"collabops","role":"백엔드 Platform 엔지니어","headline":"AI 실행 흐름과 서비스 API·배포를 연결하고 병목을 개선합니다.","summary":"문서·음성 AI 코드를 인수해 API별 실행·정제 흐름과 모델 재로딩 구조를 개선하고 Node.js API·Nginx·HTTPS 배포를 담당했습니다. HTM의 요구사항·구조 설계와 AWS 환경 분리·GitHub Actions 운영 자동화, Kafka·Redis를 통한 영상 분석 결과 연계 경험이 있습니다. 기존 구조를 읽고 실행 흐름을 서비스로 연결하는 일을 해왔습니다.","order":["document-ai","htm","vision","mangwon"]},{"id":"tura","role":"AI·커머스 업무자동화 개발자","headline":"반복되는 업무를 데이터 흐름과 자동화 도구로 바꿉니다.","summary":"HTM의 근태·스케줄·채용 요구를 업무 규칙과 화면 흐름으로 정리하고 AI를 활용해 구현·운영했습니다. 방문객 통계 조회·비교 도구와 HTML·ChatGPT API 보고서, 문서 AI 결과의 Markdown·JSON 정제 경험도 있습니다. 실제 사용자의 업무를 분석하고 결과를 확인하며 도구를 개선하는 방식으로 일해왔습니다.","order":["htm","mangwon","document-ai","vision"]}];
window.RESUME_FACTS={"htm":{"title":"HTM · 업무 시스템 설계·배포·운영","company":"위더스코퍼레이션","date":"2026.02–현재 · 프리랜서","bullets":["요구사항·업무 규칙, 시스템 구조와 화면 흐름을 설계하고 Claude Code를 활용해 구현·수정·배포·운영을 진행했습니다.","서비스 계정과 조직 소속을 구분하고 채용 확정→조직 멤버 전환→매장 배정 흐름, 스케줄·태블릿 출퇴근·직원용 웹을 구성했습니다.","staging 배포·cron 실행·CPU·메모리 부족·DB 병목 등의 운영 영향에 대응해 공유 EC2·RDS를 환경별로 분리했습니다.","GitHub Actions로 staging 기동·중지·production DB 기준 동기화를 구성하고 필요 시 운영하는 방식을 설계·적용했습니다.","production EC2를 상위 사양으로 이전하고 RDS 변경을 새벽에 예약 적용했습니다. ALB 기반 무중단 배포와 S3 버전 관리·CloudFront 제공을 적용했습니다."]},"document-ai":{"title":"문서·음성 AI 파이프라인 개선 및 API 서비스화","company":"주식회사 애나","date":"2025.06–2026.02 · 계약직","bullets":["매뉴얼·양식 관련 AI 질의응답 과제의 기존 처리 코드를 인수해 API별 실행 흐름과 데이터 정제 과정을 개선했습니다.","여러 OCR 모델의 단독·조합 적용을 테스트하고 추출 결과를 LLM으로 정제하는 흐름과 Markdown·JSON 출력을 다뤘습니다. 음성 인식 실행 설정과 일부 파라미터도 조정했습니다.","요청마다 모델을 다시 불러오던 구조와 PDF 분석·Markdown 변환의 처리 지연을 개선했습니다.","한글 인식 오류를 코드 디버깅과 자료 조사로 추적하고 관련 파일 교체로 인식 품질을 개선했습니다.","Node.js API 서버와 Nginx 리버스 프록시·Certbot HTTPS 환경 구성·배포를 단독 담당했습니다."]},"vision":{"title":"CCTV 오토라벨링 성능 개선·실시간 분석 연계","company":"주식회사 애나","date":"2025.06–2026.02 · 계약직","bullets":["군중 인식 모델의 점 좌표·밀도 맵을 활용한 박스 후보 생성·조정과 YOLO 사람 여부 검증 흐름을 개선했습니다.","영상 추출·점 좌표·박스 생성 모듈을 개별 실행하고 단계별 디버깅으로 병목을 추적했습니다. Claude 웹으로 대안을 검토하고 탐색 구조를 변경했습니다.","다음 날까지 완료되지 않기도 하던 작업을 당시 테스트에서 1시간 이내에 완료하도록 개선했습니다.","H100에서 모델별 분석 프로세스를 실행하고 RTSP 군중 분석 결과를 Kafka·Redis와 연계해 프로그램 서버로 전달했습니다.","쓰러짐·화재·싸움 관련 데이터를 수집·보완하고 모델 학습과 선별 영상 기반 시연을 진행했습니다."]},"mangwon":{"title":"00시장 방문객 통계·조회 도구·AI 보고서","company":"주식회사 애나 경력 중 개별 수행 사례","date":"약 1개월","bullets":["YOLO로 사람을 탐지하고 별도 모델로 성별·나이대를 추정한 결과를 Python에서 조합해 통계를 생성했습니다. WinForms 뷰어의 CCTV별·시간대별 조회·비교를 구현했습니다.","통계 기반 HTML 보고서와 ChatGPT API를 연동한 분석 문구 생성 기능을 구성했습니다.","영상 분석 결과를 사용자가 조회·비교·보고서 작성에 활용할 수 있는 흐름으로 연결했습니다."]}};
